-- GENERATED by scripts/gen_taxonomy.py from 'Industry & Career List Revisions v2'.
-- SKILLED Nation two-level taxonomy: sectors + career fields.

CREATE TABLE IF NOT EXISTS public.sectors (
  code          TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  full_name     TEXT NOT NULL,
  description   TEXT NOT NULL DEFAULT '',
  examples      TEXT NOT NULL DEFAULT '',
  display_order INT  NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO public.sectors (code, name, full_name, description, examples, display_order)
VALUES ('construction', 'Construction & Building Trades', 'Construction & Building Trades', 'Building, renovating, and repairing homes, commercial buildings, roads, bridges, and other structures.', 'Carpenter, electrician, plumber, HVAC technician, mason, roofer, welder, heavy equipment operator', 0)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, full_name = EXCLUDED.full_name,
  description = EXCLUDED.description, examples = EXCLUDED.examples,
  display_order = EXCLUDED.display_order;
INSERT INTO public.sectors (code, name, full_name, description, examples, display_order)
VALUES ('manufacturing', 'Manufacturing', 'Manufacturing', 'Making physical products using machinery, tools, robotics, automation, machining, and quality-control systems. Includes traditional factory work as well as high-tech production.', 'CNC machinist, industrial maintenance technician, welder/fabricator, tool-and-die maker, mechatronics technician, robotics technician', 1)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, full_name = EXCLUDED.full_name,
  description = EXCLUDED.description, examples = EXCLUDED.examples,
  display_order = EXCLUDED.display_order;
INSERT INTO public.sectors (code, name, full_name, description, examples, display_order)
