INSERT INTO public.sectors (code, name, full_name, description, examples, display_order)
VALUES ('data_it', 'Data & Information Technology', 'Data & Information Technology', 'Building, maintaining, and repairing infrastructure, hardware, and software related to information technology and data storage. Primarily focused on non-4 year and advanced degrees.', 'Database administrators, network and IT support specialist, network and computer systems administrator,', 5)
