INSERT INTO public.sectors (code, name, full_name, description, examples, display_order)
VALUES ('telecom', 'Telecommunications', 'Telecommunications', 'Installing, maintaining, and troubleshooting the physical systems that support internet, phone, security, data, and connected-building technologies. This overlaps with construction, utilities, and IT.', 'Fiber optic technician, cable installer, low-voltage electrical technician, security systems installer, network cabling technician', 6)
