INSERT INTO public.sectors (code, name, full_name, description, examples, display_order)
VALUES ('public_safety', 'Public & Emergency Service', 'Public & Emergency Service', 'Careers focused on protecting people, property, and communities. Not all public safety jobs are “trades” in the traditional sense, but many are hands-on, skill-based, credentialed career paths.', 'Firefighter, EMT/paramedic, fire alarm technician, emergency vehicle technician, public safety communications technician, various municipal and civil service positions', 7)
